import subprocess
import time
import threading
def task_func(file_list):
    exit_codes = [None] * len(file_list)

    def run_process(file_path, index):
        try:
            process = subprocess.Popen([file_path])
            process.wait()
            exit_codes[index] = process.returncode
        except Exception:
            exit_codes[index] = -1

    threads = []
    for i, file_path in enumerate(file_list):
        thread = threading.Thread(target=run_process, args=(file_path, i))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return exit_codes

