import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder) or not os.path.exists(dst_folder):
        return {'success': False, 'message': 'Source or destination folder does not exist.', 'failed_files': []}

    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]
    failed_files = []

    for file_path in files:
        try:
            subprocess.run(['gzip', '-k', file_path], check=True)
            gz_file = file_path + '.gz'
            shutil.move(gz_file, os.path.join(dst_folder, os.path.basename(gz_file)))
        except Exception:
            failed_files.append(os.path.basename(file_path))

    success = len(failed_files) == 0
    message = 'All files processed successfully.' if success else 'Some files failed to process.'

    return {'success': success, 'message': message, 'failed_files': failed_files}

